def dart(s): return 'void main() {\n'+s+'\n}\n'
def scala(s): return '@main def lesson(): Unit =\n'+'\n'.join('  '+line for line in s.splitlines())+'\n'
def perl(s): return 'use strict;\nuse warnings;\nuse feature "say";\n'+s+'\n'
course('dart','Dart','dart','Examples use Dart 3 or later.','Install Dart 3 or later. Save one example as lesson.dart and run dart run lesson.dart. Flutter is not needed for these language lessons.','Dart is a language used for apps and tools. Flutter uses Dart to build screens.',[
L('first-message','Print a greeting','main is where this Dart program starts. print shows a value.',dart('print("Hello, Asha!");'),'Hello, Asha!','Change the name.','Keep the main function around the steps.'),
L('variables','Keep a named number','var lets Dart work out a type from a value. Numbers can be added with +.',dart('var pencils = 3;\nprint(pencils + 2);'),'5','Start with 6 pencils.','A variable set to an int cannot later hold text.'),
L('final','Keep a value fixed','final means a name can be assigned only once. It helps protect a value from accidental changes.',dart('final days = 7;\nprint(days);'),'7','Try assigning days a new value and read the error.','final prevents reassignment, not every change inside a mutable object.'),
L('strings','Build a text message','A dollar sign places a variable inside a Dart string.',dart('var name = "Ravi";\nprint("Hi, $name!");'),'Hi, Ravi!','Include a score in a message.','Use ${...} to insert a calculation.'),
L('choices','Make a choice','if checks a Boolean rule. The else branch runs when that rule is false.',dart('var score = 8;\nif (score >= 5) { print("Pass"); } else { print("Try again"); }'),'Pass','Try score 3.','A number by itself is not a Boolean condition.'),
L('lists','Add a list item','A List keeps values in order. add places a new value at the end.',dart('var scores = [4, 5];\nscores.add(8);\nprint(scores);'),'[4, 5, 8]','Add 9 too.','The first position in a List is zero.'),
L('loops','Visit each item','for-in reads each value of a list in order.',dart('for (var pet in ["cat", "dog"]) { print(pet); }'),'cat\ndog','Add fish to the list.','The loop variable holds one item at a time.'),
L('functions','Return a small result','A function gives a calculation a name. The arrow form returns one expression.','int twice(int n) => n * 2;\nvoid main() { print(twice(4)); }','8','Call twice with 7.','The returned value must fit the declared type.'),
L('maps','Use named keys','A Map pairs keys and values. It can find a value by a text label.',dart('var book = {"title": "Moon Trip", "pages": "24"};\nprint(book["title"]);'),'Moon Trip','Look up the pages key.','A missing map key gives null.'),
L('null-safety','Choose a fallback','String? can hold text or null. ?? chooses a fallback when the value is null.',dart('String? name;\nprint(name ?? "Guest");'),'Guest','Give name the value Asha.','Using ! on null causes an error.'),
L('classes','Make a small object','A class is a plan for objects. Its constructor fills in the starting fields.','class Book {\n  final String title;\n  Book(this.title);\n}\nvoid main() { print(Book("Moon Trip").title); }','Moon Trip','Create a book with a different title.','Use the constructor inputs in the right order.'),
L('async','Wait for a future value','A Future represents a result that may arrive later. await reads that result inside an async function.','Future<void> main() async {\n  final score = await Future.value(8);\n  print(score);\n}','8','Change the future value to 6.','await belongs in an async function.')])
course('r','R','r','Examples use base R 4.2 or later; no extra packages are needed.','Install R. Save an example as lesson.R and run Rscript lesson.R, or paste it into the R console.','R is a language for exploring numbers and data. It is useful for tables, summaries and charts.',[
L('first-message','Show text','cat joins values and writes them out. A backslash-n adds a new line.','cat("Hello, Asha!\\n")','Hello, Asha!','Change the greeting.','Unlike print, cat does not add a new line unless you ask.'),
L('values','Name a value','The <- arrow assigns a value to a name. Here pencils keeps the number 3.','pencils <- 3\ncat(pencils + 2, "\\n")','5','Start with 6 pencils.','Use a number without quotes for maths.'),
L('vectors','Keep several numbers','A vector is an ordered group of values. c combines values into a vector.','scores <- c(4, 5, 8)\ncat(scores, "\\n")','4 5 8','Add another score.','R positions start at 1, unlike many other languages.'),
L('indexing','Read a position','Square brackets select values. Position 2 is the second item in R.','pets <- c("cat", "dog")\ncat(pets[2], "\\n")','dog','Read pets[1].','Index zero gives an empty selection, not the first item.'),
L('vector-maths','Do maths on a vector','R can apply arithmetic to each value in a vector.','scores <- c(2, 3)\ncat(scores * 2, "\\n")','4 6','Multiply by 3.','Different vector lengths can cause recycling; check their lengths.'),
L('filtering','Keep matching values','A logical test makes true-or-false values. Use them in brackets to keep matching numbers.','scores <- c(4, 8, 9)\ncat(scores[scores >= 7], "\\n")','8 9','Change the limit to 9.','The filter must describe the values you intend to keep.'),
L('summaries','Find a mean','mean adds values and divides by their count. This is the average.','cat(mean(c(2, 4, 6)), "\\n")','4','Find the mean of 4, 6 and 8.','Missing values need an explicit plan, such as na.rm = TRUE.'),
L('missing-data','Handle missing data','NA marks a missing value. is.na detects it.','scores <- c(4, NA, 8)\ncat(sum(is.na(scores)), "\\n")','1','Add another NA.','Do not compare with == NA; use is.na.'),
L('data-frames','Make a data table','A data frame stores columns of the same row count. Each column has a name.','books <- data.frame(title = c("Moon", "Sun"), pages = c(24, 30))\ncat(books$pages, "\\n")','24 30','Read the title column.','Keep all columns the same length.'),
L('functions','Name a calculation','function defines reusable steps. R returns its final expression.','twice <- function(n) { n * 2 }\ncat(twice(4), "\\n")','8','Call twice(7).','Remember to call the function with parentheses.'),
L('choices','Choose a message','if checks one true-or-false value. else chooses the other action.','score <- 8\nif (score >= 5) { cat("Pass\\n") } else { cat("Try again\\n") }','Pass','Try score 3.','A whole vector is not one if condition; choose a single rule.'),
L('sorting','Put values in order','sort returns a vector in order from smallest to largest by default.','cat(sort(c(8, 3, 5)), "\\n")','3 5 8','Use decreasing = TRUE.','sort returns a result; keep it if you want to reuse it.')])
course('matlab','MATLAB','matlab','Examples use MATLAB R2020b or later and basic built-in commands.','Use MATLAB. Paste one example into the Command Window, or save it as a .m script and run the script. A MATLAB licence may be required.','MATLAB works with numbers, rows and grids of data. A grid of numbers is called a matrix.',[
L('first-message','Show a message','disp displays a value. Single quotes can hold a row of characters.','disp(\'Hello, Asha!\');','Hello, Asha!','Change the name.','Use matching quotes for text.'),
L('variables','Name a value','A variable stores a value. A semicolon hides the automatic display of an assignment.','pencils = 3;\ndisp(pencils + 2);','5','Start with 6 pencils.','Without a semicolon MATLAB also shows the assignment result.'),
L('vectors','Make a row of values','Square brackets build a row vector, which is a line of values.','scores = [4 5 8];\nfprintf(\'%d %d %d\\n\', scores);','4 5 8','Add another value and adjust the display format.','Commas or spaces divide items in a row.'),
L('indexing','Read one position','MATLAB indexing starts at 1. Parentheses select an item.','scores = [4 5 8];\ndisp(scores(2));','5','Read the third item.','Index zero is not allowed.'),
L('matrices','Read a grid cell','Semicolons divide matrix rows. A cell is selected by row, then column.','grid = [1 2; 3 4];\ndisp(grid(2,1));','3','Read row 1, column 2.','Write row before column in the index.'),
L('element-maths','Multiply each item','The dot in .* means element-by-element multiplication. Each matching pair is multiplied.','a = [2 3];\nb = [4 5];\nfprintf(\'%d %d\\n\', a .* b);','8 15','Change b to [1 2].','Plain * means matrix multiplication, which is a different operation.'),
L('ranges','Make an evenly spaced row','The colon form start:step:end builds evenly spaced values.','numbers = 1:2:5;\nfprintf(\'%d %d %d\\n\', numbers);','1 3 5','Use a step of 1.','The middle number is a step size, not an item count.'),
L('filtering','Keep matching numbers','A logical test makes a true-or-false mask for selecting values.','scores = [4 8 9];\nkept = scores(scores >= 7);\nfprintf(\'%d %d\\n\', kept);','8 9','Use a limit of 9.','Use parentheses for indexing, not square brackets.'),
L('mean','Find an average','mean returns the average. For this row it adds three numbers and divides by three.','disp(mean([2 4 6]));','4','Find the mean of [4 6 8].','For a matrix, check which dimension mean works along.'),
L('choices','Use a condition','if chooses a block of steps. end closes the block.','score = 8;\nif score >= 5\n disp(\'Pass\');\nelse\n disp(\'Try again\');\nend','Pass','Try score 3.','Do not forget end after the if block.'),
L('loops','Repeat counted steps','A for loop visits each value in the row after the equals sign.','for n = 1:3\n fprintf(\'%d\\n\', n);\nend','1\n2\n3','Count up to 4.','The loop variable changes each time; do not reset it inside.'),
L('functions','Use an anonymous function','An anonymous function is a short function value. @(n) names its input.','twice = @(n) n * 2;\ndisp(twice(4));','8','Call twice(7).','Use . operators when a function should work item by item on arrays.')])
course('scala','Scala','scala','Examples use Scala 3.3 or later and Scala CLI.','Install Scala CLI. Save each example as lesson.scala and run scala run lesson.scala. These examples use Scala 3 syntax.','Scala combines object tools with functions and strong types. It runs on the Java virtual machine.',[
L('first-message','Print a greeting','@main marks a starting function. println prints text.',scala('println("Hello, Asha!")'),'Hello, Asha!','Change the name.','Keep the indented body under the function.'),
L('values','Keep a fixed value','val names a value that cannot be reassigned.',scala('val pencils = 3\nprintln(pencils + 2)'),'5','Start with 6 pencils.','Use var only when reassignment is needed.'),
L('text','Build a message','An s string can insert a variable with a dollar sign.',scala('val name = "Ravi"\nprintln(s"Hi, $name!")'),'Hi, Ravi!','Insert a score too.','The s before the quotes enables interpolation.'),
L('choices','Choose a result','An if expression can return one of two values.',scala('val score = 8\nval message = if score >= 5 then "Pass" else "Try again"\nprintln(message)'),'Pass','Try score 3.','An expression that must return a value needs both branches.'),
L('lists','Store a list','List holds items in order. head reads the first item.',scala('val pets = List("cat", "dog")\nprintln(pets.head)'),'cat','Read pets.tail.head.','head fails on an empty list; headOption is safer when it may be empty.'),
L('map','Transform every item','map builds a new list by applying a function to each item.',scala('val doubled = List(2, 3).map(n => n * 2)\nprintln(doubled.mkString(", "))'),'4, 6','Multiply by 3.','The old list stays unchanged.'),
L('filter','Keep matching items','filter keeps items for which its function returns true.',scala('val kept = List(4, 8, 9).filter(_ >= 7)\nprintln(kept.mkString(", "))'),'8, 9','Raise the limit to 9.','The underscore stands for the current item here.'),
L('functions','Name a calculation','def defines a function. Its input and return type are shown with colons.',scala('def twice(n: Int): Int = n * 2\nprintln(twice(4))'),'8','Call twice(7).','The returned result must match the declared type.'),
L('option','Handle an absent value','Option holds Some(value) or None. getOrElse gives a fallback.',scala('val score: Option[Int] = None\nprintln(score.getOrElse(0))'),'0','Use Some(8).','Calling get on None throws an error.'),
L('matching','Match a named choice','match checks cases from top to bottom. _ is a catch-all case.',scala('val light = "green"\nval message = light match\n  case "red" => "Stop"\n  case "green" => "Go"\n  case _ => "Wait"\nprintln(message)'),'Go','Try yellow.','Keep case lines indented under match.'),
L('case-classes','Group data fields','A case class is a handy data type with named fields and value-based equality.',scala('case class Book(title: String, pages: Int)\nval book = Book("Moon Trip", 24)\nprintln(book.pages)'),'24','Make a copy with pages = 30.','copy creates a new value rather than changing the old one.'),
L('fold','Combine a list','foldLeft starts with one value and combines it with each list item.',scala('val total = List(2, 3, 4).foldLeft(0)(_ + _)\nprintln(total)'),'9','Start the fold at 10.','The starting value affects the final result.')])
course('perl','Perl','perl','Examples use Perl 5.20 or later with strict checks.','Install Perl 5. Save one example as lesson.pl and run perl lesson.pl.','Perl is a language used for scripts, text processing and small automation jobs.',[
L('first-message','Print a greeting','say prints text and adds a newline. The feature line enables it.',perl('say "Hello, Asha!";'),'Hello, Asha!','Change the name.','Keep use feature "say" when using say on these versions.'),
L('scalars','Name a single value','A scalar keeps one value. Its name starts with $. my declares the variable.',perl('my $pencils = 3;\nsay $pencils + 2;'),'5','Start with 6 pencils.','Declare variables with my when strict is enabled.'),
L('strings','Insert text values','Double-quoted strings insert scalar variables into text.',perl('my $name = "Ravi";\nsay "Hi, $name!";'),'Hi, Ravi!','Add another variable.','Single quotes keep the dollar text literal.'),
L('arrays','Keep an ordered list','An array name starts with @. Read one item with $ and its zero-based position.',perl('my @pets = ("cat", "dog");\nsay $pets[1];'),'dog','Read the first item.','Use $pets[1] for one item, not @pets[1].'),
L('hashes','Use text keys','A hash pairs keys with values. Curly braces select a value by key.',perl('my %book = (title => "Moon Trip", pages => 24);\nsay $book{title};'),'Moon Trip','Read pages instead.','A whole hash uses %, but one selected value uses $.'),
L('choices','Choose an action','if runs a block when the test is true.',perl('my $score = 8;\nif ($score >= 5) { say "Pass"; } else { say "Try again"; }'),'Pass','Try score 3.','Use braces around the selected steps.'),
L('string-tests','Compare text','eq compares text. == is the numeric comparison operator.',perl('my $pet = "cat";\nsay $pet eq "cat" ? "Yes" : "No";'),'Yes','Try the value dog.','Using == for words can cause unwanted number conversion.'),
L('loops','Visit each value','for can visit each value in a list. The loop variable holds the current value.',perl('for my $n (1..3) { say $n; }'),'1\n2\n3','Count to 4.','The range 1..3 includes both ends.'),
L('subroutines','Name reusable steps','A subroutine is a named set of steps. @_ holds its inputs.',perl('sub twice { my ($n) = @_; return $n * 2; }\nsay twice(4);'),'8','Call twice(7).','Copy the input from @_ before using it.'),
L('regex-match','Find a text pattern','A regular expression describes a pattern. =~ asks whether the string matches it.',perl('my $word = "cat";\nsay $word =~ /^c/ ? "Starts with c" : "Other";'),'Starts with c','Try dog.','^ means the start, so c must be the first character.'),
L('substitution','Replace matching text','s/old/new/ replaces matching text. The g flag replaces all matches.',perl('my $text = "red red";\n$text =~ s/red/blue/g;\nsay $text;'),'blue blue','Remove g and compare.','Without g, only the first match is replaced.'),
L('split-join','Split and join text','split breaks text at a pattern. join puts a list together with a separator.',perl('my @words = split /,/, "cat,dog";\nsay join " + ", @words;'),'cat + dog','Add fish to the comma-separated text.','The separator used by split is a pattern, not always plain text.')])
course('lua','Lua','lua','Examples use Lua 5.3 or 5.4.','Install Lua 5.3 or 5.4. Save each example as lesson.lua and run lua lesson.lua.','Lua is a small language often placed inside games and other apps to let them run scripts.',[
L('first-message','Print a greeting','print shows a value and moves to a new line.','print("Hello, Asha!")','Hello, Asha!','Change the name.','Keep matching quotes around text.'),
L('locals','Keep a local value','local limits a name to its part of the program. This helps avoid accidental global names.','local pencils = 3\nprint(pencils + 2)','5','Start with 6 pencils.','Use local unless a name really needs to be global.'),
L('text','Join text','Two dots join text in Lua. Joining text is called concatenation.','local name = "Ravi"\nprint("Hi, " .. name .. "!")','Hi, Ravi!','Add a score to a message.','Use .. to join text, not +.'),
L('choices','Choose a message','if checks a condition. then starts its steps and end closes them.','local score = 8\nif score >= 5 then\n print("Pass")\nelse\n print("Try again")\nend','Pass','Try score 3.','Remember both then and end.'),
L('tables-list','Use a table as a list','A table can act as an ordered list. The usual first position is 1.','local pets = {"cat", "dog"}\nprint(pets[2])','dog','Read position 1.','Index zero is not the first list item in ordinary Lua tables.'),
L('tables-keys','Use named table fields','A table can also pair names with values. A dot reads a named field.','local book = { title = "Moon Trip", pages = 24 }\nprint(book.title)','Moon Trip','Read book.pages.','A field that is not present gives nil.'),
L('counting','Count with a for loop','A numeric for loop includes both its start and end values.','for n = 1, 3 do\n print(n)\nend','1\n2\n3','Count up to 4.','Use a comma between start and end, not a range operator.'),
L('ipairs','Visit list items','ipairs gives a position and value for list-style entries starting at 1.','for _, pet in ipairs({"cat", "dog"}) do\n print(pet)\nend','cat\ndog','Add fish to the table.','ipairs stops at the first missing numbered value.'),
L('functions','Return a result','A function is a named group of steps. return sends a value back.','local function twice(n)\n return n * 2\nend\nprint(twice(4))','8','Call twice(7).','Close the function with end before calling it.'),
L('nil','Use a fallback','nil means no value. or chooses the second value when the first is nil or false.','local name = nil\nprint(name or "Guest")','Guest','Set name to Asha.','Zero and empty strings are true values in Lua.'),
L('multiple-results','Return two values','Lua functions can return several values. A matching assignment reads them.','local function pair()\n return 3, 5\nend\nlocal a, b = pair()\nprint(a + b)','8','Return 4 and 6.','One receiving variable keeps only the first returned value.'),
L('protected-calls','Catch a failed call','pcall runs a function and reports whether it succeeded. The first result is true or false.','local ok = pcall(function() error("Try again") end)\nprint(ok)','false','Replace error with return 8 and check ok.','The error message is a second result; the first result is the success flag.')])
